from packages.utils import compute_freqs
import numpy as np
import h5py


def save_simulation(filename, sim_name, data, specs):

    with h5py.File(filename, "a") as f:

        sim = f.require_group(sim_name)

        # Numerical data: matrices, arrays, etc.
        for name, value in data.items():
            if name in sim:
                del sim[name]

            sim.create_dataset(name, data=value)

        # Specifications / metadata
        for name, value in specs.items():
            sim.attrs[name] = value


